pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address account, address admin) public {
        vm.assume(admin != address(0) && admin != address(this));
        vm.assume(account != address(0) && account != address(this));
        // Use the default admin role (0x00) to grant roles, since DEFAULT_ADMIN_ROLE is the admin of all roles by default.
        bytes32 adminRole = 0x00;
        // The setup: we must be able to grant the role to test.
        // Give admin the DEFAULT_ADMIN_ROLE so it can call grantRole.
        vm.prank(address(this));
        c.grantRole(adminRole, admin);

        // admin grants role to account
        vm.prank(admin);
        c.grantRole(role, account);

        // assert: hasRole must reflect the granted role
        assertTrue(c.hasRole(role, account));
    }
}

