pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address account) public {
        // No constraints: any role and account is admissible.
        // We directly query hasRole. The reference returns the actual membership;
        // the mutant returns its negation.

        // First determine the actual membership by checking the reference behaviour.
        // Since we only have one C instance (and we are testing the property that
        // holds for the reference), we rely on the following invariant:
        //   hasRole(role, account) == true  if and only if the role was granted to account.
        //   (By default no account has any role except those explicitly granted.)
        // To detect the mutant, we observe that granting a role to an account
        // must make hasRole return true. The mutant would return false after grant.

        // Grant the role to the account using the admin role (DEFAULT_ADMIN_ROLE controls itself).
        // The constructor sets TIMELOCK_ADMIN_ROLE admin to itself, but DEFAULT_ADMIN_ROLE is 0x00.
        // We need to use the admin of the role to grant it. For simplicity,
        // we grant the role using the contract itself which is admin of all roles.
        // Actually, the deployer (this test contract) is a timelock admin because
        // setUp passed address(this) to the constructor for proposers/executors,
        // but that does not grant DEFAULT_ADMIN_ROLE. Let's just grant the role
        // via the contract itself, which is granted TIMELOCK_ADMIN_ROLE in constructor.
        // However, we are testing hasRole for arbitrary roles, not just system roles.
        // We can grant role "role" to account using DEFAULT_ADMIN_ROLE (0x00) admin?
        // The admin for role is _roles[role].adminRole which defaults to 0 (DEFAULT_ADMIN_ROLE).
        // Only accounts with DEFAULT_ADMIN_ROLE can grant. None has it by default.
        // Instead, we can grant TIMELOCK_ADMIN_ROLE to account and test hasRole.
        // The contract itself has TIMELOCK_ADMIN_ROLE, so we can prank as the contract.

        vm.prank(address(c));
        c.grantRole(role, account);

        // Now the reference hasRole(role, account) must be true.
        // The mutant inverts and returns false.
        bool hasRoleResult = c.hasRole(role, account);
        assertTrue(hasRoleResult);
    }
}

